import{_ as s,C as a,o,c as l,a2 as t,E as n}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Featured Sellers","description":"","frontmatter":{},"headers":[],"relativePath":"storefront/featured-sellers.md","filePath":"storefront/featured-sellers.md","lastUpdated":1789411447000}'),i={name:"storefront/featured-sellers.md"};function d(u,e,h,p,c,g){const r=a("ImagePopup");return o(),l("div",null,[e[0]||(e[0]=t('<h1 id="featured-sellers" tabindex="-1">Featured Sellers <a class="header-anchor" href="#featured-sellers" aria-label="Permalink to &quot;Featured Sellers&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span><span class="role role--admin">Admin</span></div><p>Featured sellers give your best sellers extra visibility. The <strong>Our Featured Sellers</strong> block appears on the marketplace landing page, between the features and the seller journey. It isn&#39;t shown on the store&#39;s home page.</p>',3)),n(r,{src:"/images/featured-sellers/featured-sellers-block.png",alt:"The Our Featured Sellers block on the marketplace landing page"}),e[1]||(e[1]=t('<h2 id="what-customers-see" tabindex="-1">What customers see <a class="header-anchor" href="#what-customers-see" aria-label="Permalink to &quot;What customers see&quot;">​</a></h2><p>Each seller card shows:</p><ul><li>the seller&#39;s logo;</li><li>their business name, which opens their shop page;</li><li>their address;</li><li>their star rating and number of reviews, counting approved reviews only.</li></ul><h2 id="how-sellers-are-chosen" tabindex="-1">How sellers are chosen <a class="header-anchor" href="#how-sellers-are-chosen" aria-label="Permalink to &quot;How sellers are chosen&quot;">​</a></h2><p>The marketplace picks the sellers for you. You can&#39;t pin or hide a particular seller.</p><p>A seller can be featured when they are:</p><ul><li>approved and not suspended;</li><li>a shop owner with a business name, not a team member;</li><li>selling on the current channel;</li><li>on an active plan, when the store uses subscription plans.</li></ul><p>The eligible sellers are then ranked by the <strong>Popularity Criteria</strong> you choose:</p><table tabindex="0"><thead><tr><th>Criteria</th><th>Ranks sellers by</th></tr></thead><tbody><tr><td><strong>Maximum Orders</strong></td><td>Number of orders, whatever their status</td></tr><tr><td><strong>Maximum Products</strong></td><td>Number of products they list, including products waiting for approval and offers on other products</td></tr><tr><td><strong>Maximum Rating</strong></td><td>Average rating from approved reviews</td></tr><tr><td><strong>Maximum Sale</strong></td><td>Total value of their orders</td></tr><tr><td><strong>All</strong></td><td>Orders first, then products, rating and sales to break ties</td></tr></tbody></table><p>The top sellers, up to the <strong>Limit Count</strong>, are shown. When no seller qualifies, the block isn&#39;t shown.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Marketplace &gt;&gt; Featured Sellers</strong>.</li><li>Switch <strong>Status</strong> on.</li><li>Set the <strong>Limit Count</strong> and <strong>Popularity Criteria</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The block also needs <strong>Show Publicly</strong> switched on in <a href="./../configuration/sellers">Sellers settings</a>. See <a href="./../configuration/featured-sellers">Featured Sellers settings</a>.</p>',13))])}const b=s(i,[["render",d]]);export{f as __pageData,b as default};
